/**
 * Copy the generated LLM documents next to the built site.
 *
 * `llms.txt` is generated by `packages/ui`'s registry build, so publishing
 * it from there means it can never describe a component the registry does not
 * have. This site only serves it.
 */

import { copyFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const packageRoot = resolve(here, "..", "..", "..", "packages", "ui");
const publicDir = resolve(here, "..", "public");

await copyFile(resolve(packageRoot, "llms.txt"), resolve(publicDir, "llms.txt"));
await copyFile(resolve(packageRoot, "llms-full.txt"), resolve(publicDir, "llms-full.txt"));

console.log("llms.txt and llms-full.txt → apps/docs/public");
